SELECT qryInvoiceAttachRPT.CaseID, qryInvoiceAttachRPT.Bill_ID, TblCase.Last_Name, TblCase.First_Name, qryInvoiceAttachRPT.[Bill Sent], qryInvoiceAttachRPT.[Bill Paid], qryInvoiceAttachRPT.[Bill Closed], qryInvoiceAttachRPT.[BilL Closed Date], qryInvoiceAttachRPT.Discount, qryInvoiceAttachRPT.CaseNo, qryInvoiceAttachRPT.IANumber, qryInvoiceAttachRPT.Tdate, qryInvoiceAttachRPT.Description, qryInvoiceAttachRPT.Tatty, qryInvoiceAttachRPT.Rate, qryInvoiceAttachRPT.Time_, [Last_name] & IIf(IsNull([first_name]),Null," " & [first_name]) AS FullName, Nz([time_],0)*Nz([rate],0) AS Amount, qryInvoiceAttachRPT.TimeNotes, TblCase.Address, TblCase.City, TblCase.State, TblCase.ZIP, TblCase.Matter_type, TblCase.Executor
FROM qryInvoiceAttachRPT INNER JOIN TblCase ON qryInvoiceAttachRPT.CaseID = TblCase.CaseID
ORDER BY qryInvoiceAttachRPT.Tdate;